for (let i = 0; i < GameBattle.playerBattlers.length; i++) {
    let battler = GameBattle.playerBattlers[i];
    let battlerModule = battler.getModule(6) as SoModule_Battler;
    if (battlerModule.actor.AIRecord != 0) {
        battlerModule.actor.AI = battlerModule.actor.AIRecord == 1 ? true : false;
        battlerModule.actor.AIRecord = 0;
    }
}

